BEGIN TRANSACTION;

UPDATE dbo.invoices
SET customer_id = 100
WHERE id = 1;

-- Give Session 2 time to take its first lock
WAITFOR DELAY '00:00:05';

UPDATE dbo.invoice_items
SET item_name = 'Cool Keyboard'
WHERE id = 10;

COMMIT TRANSACTION;

BEGIN TRANSACTION;

UPDATE dbo.invoice_items
SET amount = 100
WHERE id = 10;

-- Give Session 1 time to take its first lock
WAITFOR DELAY '00:00:05';

UPDATE dbo.invoices
SET total = 250
WHERE id = 1;

COMMIT TRANSACTION;
